fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> Vec<i8> {
    // j should be less than m, but we'll handle gracefully
    let mut col = Vec::with_capacity(n);
    
    for i in 0..n {
        // Access input[i][j] - assuming input has n rows
        col.push(input[i][j]);
    }
    
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    let mut result = Vec::with_capacity(m);
    
    for j in 0..m {
        // Create each new row by extracting column j from input
        let mut new_row = Vec::with_capacity(n);
        for i in 0..n {
            new_row.push(input[i][j]);
        }
        result.push(new_row);
    }
    
    result
}